describe('Column Sort Direction Indication', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should display correct arrow icon for ascending sort on first column', () => {
    // Verify initial state: no sort indicators
    cy.get('[data-testid="table-header-first-column"]').should('be.visible');
    cy.get('[data-testid="sort-arrow-first-column"]').should('not.exist');

    // Click first column header to initiate sort
    cy.get('[data-testid="table-header-first-column"]').click();

    // Verify arrow icon appears and is pointing up
    cy.get('[data-testid="sort-arrow-first-column"]').should('be.visible');
    cy.get('[data-testid="sort-arrow-first-column"]').should('contain', '↑');

    // Verify table is now sorted in ascending order
    cy.get('[data-testid="table-row-first-column"]').first().should('contain', 'A');
    cy.get('[data-testid="table-row-first-column"]').last().should('contain', 'Z');
  });

  it('should display correct arrow icon for descending sort on last column', () => {
    // Verify initial state: no sort indicators
    cy.get('[data-testid="table-header-last-column"]').should('be.visible');
    cy.get('[data-testid="sort-arrow-last-column"]').should('not.exist');

    // Click last column header to initiate sort
    cy.get('[data-testid="table-header-last-column"]').click();

    // Verify arrow icon appears and is pointing down
    cy.get('[data-testid="sort-arrow-last-column"]').should('be.visible');
    cy.get('[data-testid="sort-arrow-last-column"]').should('contain', '↓');

    // Verify table is now sorted in descending order
    cy.get('[data-testid="table-row-last-column"]').first().should('contain', 'Z');
    cy.get('[data-testid="table-row-last-column"]').last().should('contain', 'A');
  });

  it('should toggle sort direction when clicking the same column header again', () => {
    // Click first column header to initiate ascending sort
    cy.get('[data-testid="table-header-first-column"]').click();
    cy.get('[data-testid="sort-arrow-first-column"]').should('be.visible');
    cy.get('[data-testid="sort-arrow-first-column"]').should('contain', '↑');

    // Click the same column header again to toggle sort direction
    cy.get('[data-testid="table-header-first-column"]').click();

    // Verify arrow icon changes to point down
    cy.get('[data-testid="sort-arrow-first-column"]').should('contain', '↓');

    // Verify table is now sorted in descending order
    cy.get('[data-testid="table-row-first-column"]').first().should('contain', 'Z');
    cy.get('[data-testid="table-row-first-column"]').last().should('contain', 'A');
  });
});
